/*
 * GP Refresh — prospectus access code check (no server).
 *
 * Checks a prospect's unique access code against window.GPR_ACCESS_CODES (gpr-access-codes.js, generated by
 * make-access-codes.js). That file holds no readable codes or PDF link: the entered code is turned into a key
 * (PBKDF2-SHA256), the key's lookup id must exist in the file, and only that key can decrypt the PDF link.
 *
 * Results: {status: "approved", downloadUrl} | {status: "denied"} | {status: "not_configured"} | {status: "unavailable"}
 * Must match make-access-codes.js (normalisation, KDF, ids and keystream).
 */
(function () {
  "use strict";
  var GPR = (window.GPR = window.GPR || {});
  var encoder = new TextEncoder();

  function data() {
    var d = window.GPR_ACCESS_CODES;
    return d && d.v === 1 && d.entries && Object.keys(d.entries).length ? d : null;
  }

  function isConfigured() {
    return !!data();
  }

  /* Case, spaces and dashes don't matter; O/I/L read as 0/1/1 (codes use Crockford base32). */
  function normalise(code) {
    return code
      .toUpperCase()
      .replace(/[^A-Z0-9]/g, "")
      .replace(/O/g, "0")
      .replace(/[IL]/g, "1");
  }

  function fromHex(hex) {
    var bytes = new Uint8Array(hex.length / 2);
    for (var i = 0; i < bytes.length; i++) bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
    return bytes;
  }

  function toHex(buffer) {
    return Array.prototype.map
      .call(new Uint8Array(buffer), function (b) {
        return ("0" + b.toString(16)).slice(-2);
      })
      .join("");
  }

  function concat() {
    var parts = Array.prototype.slice.call(arguments);
    var out = new Uint8Array(parts.reduce(function (n, p) { return n + p.length; }, 0));
    parts.reduce(function (offset, p) {
      out.set(p, offset);
      return offset + p.length;
    }, 0);
    return out;
  }

  function sha256(bytes) {
    return crypto.subtle.digest("SHA-256", bytes).then(function (b) {
      return new Uint8Array(b);
    });
  }

  function masterKey(code, d) {
    return crypto.subtle
      .importKey("raw", encoder.encode(normalise(code)), "PBKDF2", false, ["deriveBits"])
      .then(function (key) {
        return crypto.subtle.deriveBits(
          { name: "PBKDF2", hash: "SHA-256", salt: fromHex(d.salt), iterations: d.iterations },
          key,
          256
        );
      })
      .then(function (bits) {
        return new Uint8Array(bits);
      });
  }

  function decrypt(master, hex) {
    var cipher = fromHex(hex);
    var blocks = [];
    for (var i = 0; i <= Math.floor(cipher.length / 32); i++) {
      var counter = new Uint8Array([i >>> 24, (i >>> 16) & 255, (i >>> 8) & 255, i & 255]);
      blocks.push(sha256(concat(encoder.encode("gpr-enc"), master, counter)));
    }
    return Promise.all(blocks).then(function (parts) {
      var stream = concat.apply(null, parts);
      return new TextDecoder().decode(cipher.map(function (b, i) { return b ^ stream[i]; }));
    });
  }

  function safeDownloadUrl(value) {
    try {
      var url = new URL(value);
      return url.protocol === "https:" ? url.href : null;
    } catch (error) {
      return null;
    }
  }

  function verify(details) {
    var d = data();
    if (!d) return Promise.resolve({ status: "not_configured" });
    if (!window.crypto || !crypto.subtle) return Promise.resolve({ status: "unavailable" });
    var master;
    return masterKey(details.code, d)
      .then(function (key) {
        master = key;
        return sha256(concat(encoder.encode("gpr-id"), master));
      })
      .then(function (id) {
        var entry = d.entries[toHex(id)];
        if (!entry) return { status: "denied" };
        return decrypt(master, entry).then(function (text) {
          var url = safeDownloadUrl(text);
          return url ? { status: "approved", downloadUrl: url } : { status: "unavailable" };
        });
      })
      .catch(function () {
        return { status: "unavailable" };
      });
  }

  GPR.prospectus = { isConfigured: isConfigured, normalise: normalise, verify: verify };
})();
